// utils.js
import { cards } from "../data/card.js";
import { rewards } from "../data/reward.js";

function getCardById(id) {
   
    if (typeof id === 'object') return id;
  
    for (const category in cards) {
        if (cards[category][id]) {
            return { ...cards[category][id] }; 
        }
    }
    console.warn(`找不到卡牌 ID: ${id}`);
    return null;
}

export function initBattle(player, enemy) {
    
    player.deck = player.baseDeck.map((id, index) => {
        const card = getCardById(id);
        if (card) {
            return { 
                ...card, 
                uid: `${id}_init_${index}_${Date.now()}` 
            };
        }
        return null;
    }).filter(c => c);
    
    player.hand = [];
    player.discard = [];
    player.hp = player.maxHP;
    player.buff = 0;
    player.defend = 0;
    player.gameOver = false;

    enemy.deck = Array.isArray(enemy.baseDeck) 
        ? enemy.baseDeck.map((id, index) => {
            const card = getCardById(id);
            return card ? { ...card, uid: `${id}_enemy_${index}_${Date.now()}` } : null;
        }).filter(c => c)
        : [];
    
    enemy.hand = [];
    enemy.hp = enemy.maxHP;
    enemy.buff = 0;
    enemy.defend = 0;
    enemy.gameOver = false;

    shuffle(player.deck);
    shuffle(enemy.deck);
    drawCards(player, 3);
}

// 洗牌函式
export function shuffle(deck) {
    if (!Array.isArray(deck) || deck.length === 0) {
        return;
    }
    
    for (let i = deck.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [deck[i], deck[j]] = [deck[j], deck[i]];
    }
    console.log("牌已打亂");
}

// 抽牌
export function drawCards(player, amount) {
    console.log("--- 開始抽取", amount, "張卡牌 ---");
    
    for (let i = 0; i < amount; i++) {
        // --- 檢查和洗牌邏輯 ---
        if (player.deck.length === 0) {
            if (player.discard.length === 0) {
                console.log("沒有牌可以抽了！");
                break;
            }
            
            console.log("牌組沒牌 → 洗棄牌堆");
            
            player.deck.push(...player.discard);
            player.discard = []; // 清空棄牌堆
            
            shuffle(player.deck);
        }

        // --- 抽一張卡 ---
        const drawnCard = player.deck.shift(); 
        
        if (!drawnCard) {
            break;
        }
        
        player.hand.push(drawnCard);
        
        console.log(`成功抽取: ${drawnCard.name} (uid: ${drawnCard.uid})`);
    }
    
    console.log("當前手牌:", player.hand.map(c => c.name));
    console.log("--- 抽取結束 ---");
}

// 棄牌
export function discardCard(player, card) {
    if (card) {
        player.discard.push(card);
    }
}

export function generateRewards(player, count = 3) {
    
    const staticRewards = Object.values(rewards).filter(r => r.type !== 'card');

    const jobCards = cards[player.job] || {}; 
    const commonCards = cards.common || {};
    
    const validCardPool = { ...jobCards, ...commonCards };
    const validCardKeys = Object.keys(validCardPool);

    const dynamicCardRewards = [];
    
    if (validCardKeys.length > 0) {
        for (let i = 0; i < 5; i++) {
            const randomKey = validCardKeys[Math.floor(Math.random() * validCardKeys.length)];
            const card = validCardPool[randomKey];

            if (card) {
                dynamicCardRewards.push({
                    id: `reward_gen_${card.id}_${Date.now()}_${i}`, 
                    name: card.name,
                    type: 'card',
                    cardId: card.id,
                    cardData: card 
                });
            }
        }
    }

    const allCandidates = [...staticRewards, ...dynamicCardRewards];

    const shuffled = allCandidates.sort(() => Math.random() - 0.5);
    return shuffled.slice(0, count);
}
// 選擇獎勵
export function chooseReward(player, reward) {
  if (reward.type === 'money') player.coin += reward.amount || 0;
  if (reward.type === 'item') {
      player.items = player.items || [];
      player.items.push(reward);
  }
  
  if (reward.type === 'card') {
      player.baseDeck = player.baseDeck || [];
      
      const originalCard = reward.cardData;
      if (originalCard) {
          const newCard = {
              ...originalCard,
              uid: `${reward.cardId}_reward_${Date.now()}`,
              costAP: originalCard.costAP,
              costMP: originalCard.costMP
          };
          player.baseDeck.push(newCard);
      }
  }
}

export function drinkPowerPotion(player, item) {
    player.buffcount = item.buffcount;
    if (item.id.includes("power")) {
        player.attack += item.power;
        console.log("已加攻擊力");
    }
}

export function finishGameCount(player) {
    player.defend = player.baseDefend;
    if(player.buffcount > 0) {
        player.buffcount--;
        console.log("buffcount" + player.buffcount)
    }
    if(player.buffcount === 0){
        player.attack = player.baseAttack;
    }
}

export function selectEvent(event, enemy) {
    console.log(enemy);
    console.log(event.id);
    const enemyData = enemy[event.id];
    if(!enemyData) {
        console.error("找不到敵人資料", event.id);
        return null;
    }
    return enemyData;
}