// 套用卡牌效果
// js/systems/applyCardEffect.js
import { drawCards } from "./utils.js";

export function applyCardEffect(player, enemy, card, logFn, onHit) {
    console.log(`${player.name} 使用 ${card.name} (Type: ${card.type})`);

    switch (card.type) {
        // --- 攻擊類 (物理/魔法/遠程/帶Debuff) ---
        case "atk":
        case "atk_debuff":
        case "atk_ranged":
        case "atk_magic": {
            // 計算總傷害
            let dmg = card.dmg + (player.buff || 0) + (player.attack || 0);
            let debuffName = ""
            let debuffType = "";

            // 處理 Debuff
            if (card.desc.includes("燃燒")) { debuffName = "燃燒"; debuffType = "burn"; }
                else if (card.desc.includes("凍結")) { debuffName = "凍結"; debuffType = "freeze"; }
                else if (card.desc.includes("劇毒")) { debuffName = "劇毒"; debuffType = "poison"; }

            if (!enemy.debuffs) enemy.debuffs = [];

            enemy.debuffs.push({
                nmae: debuffName,
                type: debuffType,
                value: card.debuff,
                round: card.debuffRound || 2
            });

            logFn(`${enemy.name} 被施加了 [${debuffName}] (每回合扣 ${card.debuff}, 持續 ${card.debuffRound||2} 回合)`);

            if(onHit) onHit(enemy, 'debuff', debuffName);

            let oldDefend = enemy.defend;

            // 扣護甲機制
            let armorLoss = Math.min(enemy.defend, dmg);
            enemy.defend -= armorLoss;
            let actualDmg = dmg - armorLoss;

            actualDmg = Math.max(0, actualDmg);

            if(onHit) {
                if (armorLoss > 0 ) {
                    onHit(enemy, 'armor', armorLoss);
                }

                if (oldDefend > 0 && enemy.defend <= 0) {
                    onHit(enemy, 'break', '🛡️破防!')
                }

                if (actualDmg > 0) {
                    let realHpLoss = Math.min(actualDmg, enemy.hp);
                    onHit(enemy, 'damage', realHpLoss);
                }
            }

            // 扣 HP
            if (actualDmg > 0) {
                const hploss = Math.min(actualDmg, enemy.hp);
                enemy.hp -= hploss;
                logFn(`${enemy.name} 受到 ${hploss} 點傷害（剩餘 HP=${enemy.hp}, 護甲=${enemy.defend}）`);
            } else {
                logFn(`${player.name} 的攻擊被護甲完全吸收`);
            }
            break;
        }

        // --- 防禦類 ---
        case "defend":
        case "defend_magic": {
            const defAmt = card.def || 0;
            player.defend += defAmt;
            if (onHit) onHit(player, 'armor', defAmt);
            logFn(`${player.name} 獲得 ${defAmt} 護甲（目前護甲=${player.defend}）`);
            break;
        }

        // --- 治療類 ---
        case "heal": { 
            if (player.hp === player.maxHP) {
                logFn(`${player.name} 生命值已滿，無法回復`);
            } else {
                const healAmount = Math.min(card.heal, player.maxHP - player.hp);
                player.hp += healAmount;
                if(onHit) onHit(player, 'heal', healAmount);
                logFn(`${player.name} 回復 ${healAmount} 點生命`);
            }
            break;
        }

        // --- 增益類 (Buff) ---
        case "buff_atk":
        case "buff_attack": { 
            const buffValue = card.buff || card.buffDmg || 0;
            player.buff = (player.buff || 0) + buffValue;
            logFn(`${player.name} 攻擊力上升 +${buffValue}`);
            break;
        }

        // --- 抽牌類 ---
        case "draw": { 
            logFn(`${player.name} 抽取 ${card.drawAmount} 張卡牌`);
            const drawCount = card.drawAmount || 2; 
            drawCards(player, drawCount);
            break;
        }

        default:
            console.warn("未知的卡牌類型:", card.type);
            logFn(`${player.name} 使用了卡牌，但什麼事都沒發生...`);
            break;
    }   
}