<template>
  <div 
    id="player-status" 
    class="relative w-full md:w-1/3 bg-gray-800 p-4 rounded-lg shadow-xl border-t-4 transition-colors duration-200"
    :class="[
      isHit ? 'border-red-600 hit-shake shadow-[0_0_30px_red] bg-red-900/40' : '',
      isHeal ? 'border-green-500 heal-pulse shadow-[0_0_30px_#10b981] bg-green-900/40' : '',
      isArmor ? 'border-blue-500 armor-pulse shadow-[0_0_30px_#3b82f6] bg-blue-900/40' : '',
      !isHit && !isHeal && !isArmor ? 'border-gray-600' : ''
    ]"
  >
    <div v-if="showSlash" class="slash-effect" :key="hitKey"></div>
    <div v-if="showHeal" class="heal-effect" :key="healKey"></div>
    <div v-if="showArmor" class="armor-effect" :key="armorKey"></div> 

    <h2 class="text-2xl font-extrabold mb-3 text-green-400">名稱: <span>{{ player.name }}</span></h2>
    
    <div class="space-y-4">
      <div class="flex items-center justify-between text-red-400 font-semibold">
        <div class="flex items-center gap-1 whitespace-nowrap mr-2">
            <span>❤️</span> 
            <span>{{ player.hp }}/{{ player.maxHP }}</span>
        </div>
        <progress class="flex-grow h-3 rounded-full player-hp-bar mx-2" :max="player.maxHP" :value="player.hp"></progress>
        
        <div class="relative flex justify-center items-center shrink-0" :class="{'opacity-50': player.defend === 0}">
          <span class="text-3xl">🛡️</span> 
          <span class="absolute text-white font-bold text-sm shadow-black drop-shadow-md select-none">
            {{ player.defend }}
          </span>
        </div>
      </div>

      <div class="flex justify-center gap-8 py-2 border-t border-gray-700 mt-2">
        <div class="flex flex-col items-center group">
          <div class="w-14 h-14 rounded-full border-4 border-yellow-500 bg-gray-900 flex items-center justify-center shadow-[0_0_15px_rgba(234,179,8,0.4)] transition-transform group-hover:scale-110">
            <span class="text-3xl font-extrabold text-yellow-400 select-none">{{ player.ap }}</span>
          </div>
          <span class="text-xs font-bold text-yellow-500 mt-1">AP 行動</span>
        </div>

        <div class="flex flex-col items-center group">
          <div class="w-14 h-14 rounded-full border-4 border-purple-500 bg-gray-900 flex items-center justify-center shadow-[0_0_15px_rgba(168,85,247,0.4)] transition-transform group-hover:scale-110">
            <span class="text-3xl font-extrabold text-purple-400 select-none">{{ player.mp }}</span>
          </div>
          <span class="text-xs font-bold text-purple-500 mt-1">MP 魔力</span>
        </div>
      </div>

      <div class="flex justify-center mt-2" v-show="player.buff > 0">
         <span class="bg-green-900 text-green-300 px-3 py-1 rounded-full text-sm font-bold border border-green-600 shadow-sm flex items-center gap-1">
           <span>⚔️</span> 攻擊增益 +{{ player.buff }}
         </span>
      </div>
    </div>
  </div>
</template>


<script>
export default {
  name: "PlayerStats",
  props: {
    player: Object,
    isHit: Boolean,
    isHeal: Boolean,
    isArmor: Boolean
  },
  data() {
    return {
      hitKey: 0,
      healKey: 0,
      armorKey: 0,
      showSlash: false,
      showHeal: false,
      showArmor: false
    };
  },
  watch: {
    isHit(val) {
      if (val) {
        this.hitKey++;
        this.showSlash = false;

        this.$nextTick(() => {
          this.showSlash = true;
        });

        const el = this.$el;
        el.classList.remove("hit-shake");
        void el.offsetWidth;
        el.classList.add("hit-shake");

        clearTimeout(this._hitTimer);
        this._hitTimer = setTimeout(() => {
          this.$emit("reset-hit");
        }, 180);
      }
    },

    isHeal(val) {
      if (val) {
        this.healKey++;
        this.showHeal = false;

        this.$nextTick(() => {
          this.showHeal = true;
        });

        const el = this.$el;
        el.classList.remove("heal-pulse");
        void el.offsetWidth;
        el.classList.add("heal-pulse");

        clearTimeout(this._healTimer);
        this._healTimer = setTimeout(() => {
          this.$emit("reset-heal");
        }, 250);
      }
    },

    isArmor(val) {
      if (val) {
        this.armorKey++;
        this.showArmor = false;

        this.$nextTick(() => {
          this.showArmor = true;
        });

        const el = this.$el;
        el.classList.remove("armor-pulse");
        void el.offsetWidth;
        el.classList.add("armor-pulse");

        clearTimeout(this._armorTimer);
        this._armorTimer = setTimeout(() => {
          this.$emit("reset-armor");
        }, 250);
      }
    }
  }
}
</script>

<style scoped>
progress {
    -webkit-appearance: none;
    appearance: none;
    border: none;
    border-radius: 9999px; 
    height: 12px;
}
progress::-webkit-progress-bar {
    background-color: #4b5563; 
    border-radius: 9999px;
}
.player-hp-bar::-webkit-progress-value {
    background-color: #10b981; 
    border-radius: 9999px;
}

.hit-shake {
  animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both;
}

/* 揮砍效果 */
.slash-effect {
  position: absolute;
  top: 20%;
  left: 10%;
  width: 100%; 
  height: 100%; 
  pointer-events: none;
  z-index: 50;
}

/* 彎曲劍氣 */
.slash-effect::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  background: transparent;
  width: 140%;
  height: 80px; 
  border-radius: 50%;
  border-top: 5px solid #fff;
  box-shadow: 
    0 -4px 10px rgba(255, 255, 255, 0.9), 
    0 -8px 25px rgba(255, 0, 0, 0.8);
  transform: translate(-50%, -50%) rotate(35deg);
  animation: slash-anim 0.2s ease-out forwards;
}

/* 治療特效 */
.heal-pulse {
  animation: pulse-green 0.6s ease-out;
}
.heal-effect {
  position: absolute;
  inset: 0;
  border-radius: 8px;
  box-shadow: inset 0 0 40px #10b981;
  pointer-events: none;
  z-index: 50;
  animation: fade-in-out 0.6s forwards;
}

/* 護甲特效 */
.armor-pulse {
  animation: pulse-blue 0.6s ease-out;
}
.armor-effect {
  position: absolute;
  inset: 0;
  border-radius: 8px;
  background: rgba(59, 130, 246, 0.2);
  border: 2px solid #3b82f6;
  pointer-events: none;
  z-index: 50;
  animation: shield-flash 0.6s ease-out forwards;
}

@keyframes shake {
  10%, 90% { transform: translate3d(-2px, 0, 0); }
  20%, 80% { transform: translate3d(4px, 0, 0); }
  30%, 50%, 70% { transform: translate3d(-6px, 0, 0); }
  40%, 60% { transform: translate3d(6px, 0, 0); }
}

@keyframes slash-anim {
  0% { width: 0; opacity: 0.5; }
  50% { width: 140%; opacity: 1; }
  100% { width: 140%; opacity: 0; }
}

@keyframes pulse-green {
  0% { transform: scale(1); }
  50% { transform: scale(1.02); box-shadow: 0 0 20px #10b981; }
  100% { transform: scale(1); }
}

@keyframes pulse-blue {
  0% { transform: scale(1); }
  50% { transform: scale(1.02); box-shadow: 0 0 20px #3b82f6; }
  100% { transform: scale(1); }
}

@keyframes shield-flash {
  0% { opacity: 0; transform: scale(0.95); }
  30% { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(1.05); }
}

@keyframes fade-in-out {
  0% { opacity: 0; }
  20% { opacity: 1; }
  100% { opacity: 0; }
}
</style>
