//enemy.js

import { applyCardEffect } from "./applyCardEffect.js";

export async function enemyAI(player, enemy, logFn, onHit) {
    // 每次重新排序手牌，依照優先度
    const sortedHand = enemy.hand.slice().sort((a, b) => {
    
        const priority = card => {
            if (card.type === "heal") return 1;
            if (card.type.endsWith("_defend") || card.type === "defend") return 2;
            if (card.type === "buff_attack") return 3;
            if (card.type.endsWith("_attack") || card.type === "attack") return 4;
            return 5;
        };

        return priority(a) - priority(b);
    });

    // 逐張（照優先度）檢查能不能用
    for (let card of sortedHand) {

        const enoughAP = !card.costAP || enemy.ap >= card.costAP;
        const enoughMP = !card.costMP || enemy.mp >= card.costMP;
        if (!enoughAP || !enoughMP) continue;

        // Heal → 只在 HP ≤ 50% 時用
        if (card.type === "heal" && enemy.hp > enemy.maxHP * 0.5) continue;

        // Defend → 只在沒有防禦時用
        if ((card.type === "defend" || card.type.endsWith("_defend")) && enemy.defend > 0)
            continue;

        // Buff → 只用一次（如果你要限制的話）
        if (card.type === "buff_attack" && enemy.atk > enemy.baseAtk + 5)
            continue;

        // 使用卡片
        logFn(enemy.name + "使用卡牌:" + card.name);
        applyCardEffect(enemy, player, card, logFn, onHit);

        await sleep(800);
    }

    while (enemy.hand.length > 0) {
        const card = enemy.hand.pop();

        enemy.discard.push(card);

        await sleep(200);
    }
}

function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}
